import axios from 'axios';
import { getLoggedInUser } from '../utils/config.util';
import { MKDB_BASE_URL } from '../utils/env.util';
import logger from '../utils/logger.util';
import login from './login';

const listDatabases = async () => {
  let userInfo = await getLoggedInUser();
  if (!userInfo) {
    await login();
    userInfo = await getLoggedInUser();
    if (!userInfo)
      return logger.log('you must be logged in to create a database');
  }

  const res = await axios
    .get(`${MKDB_BASE_URL}/api/databases`, {
      headers: { Authorization: userInfo.apiToken },
    })
    .catch((error) => {
      logger.log('error', error);
    });

  if (res?.data) {
    logger.dev.log(`list database res`, res.data);

    const cleanedData = res.data.map((db: any) => ({
      db: db.name,
      id: db.id,
      connect: `${db.provider === 'POSTGRES' ? 'postgresql' : 'unknown'}://${
        db.username
      }:${db.auth_UNSAFE.password}@${db.host}:${db.port}/${db.dbName}`,
    }));

    logger.table(cleanedData);
  } else {
    logger.log('error fetching databases..');
  }

  return null;
};

export default listDatabases;
